REVOKE INSERT, UPDATE, DELETE ON public.users FROM PUBLIC, anon, authenticated;
DROP POLICY IF EXISTS "Users insert own sub" ON public.subscribers_public;
DROP POLICY IF EXISTS "Users update own sub" ON public.subscribers_public;
DROP POLICY IF EXISTS "Users update own" ON public.users;
REVOKE EXECUTE ON FUNCTION public.check_and_increment_ai_usage(uuid,text,integer) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.check_and_increment_ai_usage(uuid) FROM PUBLIC,anon,authenticated;
REVOKE EXECUTE ON FUNCTION public.reset_monthly_ai_requests() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.auto_grant_first_user_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN NEW; END $$;
ALTER TABLE public.subscribers_public ADD COLUMN IF NOT EXISTS free_credits_remaining integer NOT NULL DEFAULT 5;
ALTER TABLE public.subscribers_public ADD COLUMN IF NOT EXISTS free_credit_reset_at timestamptz;
ALTER TABLE public.payment_subscriptions ADD COLUMN IF NOT EXISTS entitled_price_id text;
ALTER TABLE public.payment_subscriptions ADD COLUMN IF NOT EXISTS paid_period_end timestamptz;
ALTER TABLE public.payment_subscriptions ADD COLUMN IF NOT EXISTS paid_period_start timestamptz;
ALTER TABLE public.payment_subscriptions ADD COLUMN IF NOT EXISTS pending_price_id text;
ALTER TABLE public.payment_subscriptions ADD COLUMN IF NOT EXISTS pending_effective_at timestamptz;
ALTER TABLE public.payment_credit_receipts ADD COLUMN IF NOT EXISTS issued_at timestamptz;
ALTER TABLE public.payment_credit_receipts ADD COLUMN IF NOT EXISTS payment_intent_id text;
CREATE TABLE public.credit_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,environment text NOT NULL CHECK(environment IN ('sandbox','live')),source_key text NOT NULL,price_id text,issued_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,amount integer NOT NULL CHECK(amount>0),remaining integer NOT NULL CHECK(remaining>=0),revoked integer NOT NULL DEFAULT 0,UNIQUE(environment,source_key),CHECK(remaining<=amount));
GRANT ALL ON public.credit_grants TO service_role;
ALTER TABLE public.credit_grants ENABLE ROW LEVEL SECURITY;
CREATE POLICY credit_grants_service ON public.credit_grants FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE INDEX credit_grants_balance ON public.credit_grants(user_id,environment,expires_at);
CREATE TABLE public.credit_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,amount integer NOT NULL CHECK(amount>0),expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'held',tool_name text,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.credit_reservations TO service_role;
ALTER TABLE public.credit_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY credit_reservations_service ON public.credit_reservations FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE INDEX credit_reservations_user ON public.credit_reservations(user_id,expires_at);
CREATE TABLE public.billing_accounts(user_id uuid NOT NULL,environment text NOT NULL CHECK(environment IN ('sandbox','live')),stripe_customer_id text,lock_token uuid,lock_until timestamptz,pending_session_id text,pending_price_id text,PRIMARY KEY(user_id,environment),UNIQUE(environment,stripe_customer_id));
GRANT ALL ON public.billing_accounts TO service_role;
ALTER TABLE public.billing_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_accounts_service ON public.billing_accounts FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.payment_event_receipts(environment text NOT NULL,event_id text NOT NULL,event_type text NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(environment,event_id));
GRANT ALL ON public.payment_event_receipts TO service_role;
ALTER TABLE public.payment_event_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY payment_event_receipts_service ON public.payment_event_receipts FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE TABLE public.billing_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),environment text NOT NULL,provider_key text NOT NULL,reason text NOT NULL,details jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(environment,provider_key));
GRANT ALL ON public.billing_reviews TO service_role;
ALTER TABLE public.billing_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_reviews_service ON public.billing_reviews FOR ALL TO service_role USING(true) WITH CHECK(true);
UPDATE public.subscribers_public SET free_credits_remaining=CASE WHEN subscribed THEN 0 ELSE GREATEST(0,5-COALESCE(monthly_ai_requests,0)) END,free_credit_reset_at=COALESCE(last_request_reset,free_tier_start_date,created_at);
INSERT INTO public.credit_grants(user_id,environment,source_key,issued_at,expires_at,amount,remaining)
SELECT user_id,'live','legacy:'||user_id,now(),now()+interval '3 months',GREATEST(0,COALESCE(ai_request_limit,5)+COALESCE(extra_credits,0)+COALESCE(rollover_credits,0)-COALESCE(monthly_ai_requests,0)-free_credits_remaining),GREATEST(0,COALESCE(ai_request_limit,5)+COALESCE(extra_credits,0)+COALESCE(rollover_credits,0)-COALESCE(monthly_ai_requests,0)-free_credits_remaining) FROM public.subscribers_public WHERE GREATEST(0,COALESCE(ai_request_limit,5)+COALESCE(extra_credits,0)+COALESCE(rollover_credits,0)-COALESCE(monthly_ai_requests,0)-free_credits_remaining)>0;
CREATE OR REPLACE FUNCTION public.refresh_credit_account(p_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s record; paid integer; held integer; boundary timestamptz; anchor timestamptz; months integer; active_plan text;
BEGIN
 SELECT * INTO s FROM public.subscribers_public WHERE user_id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('remaining',0,'account_status','missing'); END IF;
 SELECT entitled_price_id INTO active_plan FROM public.payment_subscriptions WHERE user_id=p_user_id AND environment='live' AND paid_period_end>now() AND entitled_price_id IS NOT NULL ORDER BY paid_period_end DESC LIMIT 1;
 IF active_plan IS NULL AND s.subscribed AND EXISTS(SELECT 1 FROM public.payment_subscriptions WHERE user_id=p_user_id AND environment='live') THEN
  UPDATE public.subscribers_public SET subscribed=false,subscription_tier=NULL,subscription_package=NULL,free_tier_start_date=now(),free_credit_reset_at=now(),free_credits_remaining=5 WHERE user_id=p_user_id;
  SELECT * INTO s FROM public.subscribers_public WHERE user_id=p_user_id;
 END IF;
 IF NOT s.subscribed THEN
  anchor:=COALESCE(s.free_tier_start_date,s.created_at); months:=GREATEST(0,(extract(year FROM age(now(),anchor))*12+extract(month FROM age(now(),anchor)))::integer); boundary:=anchor+make_interval(months=>months);
  IF boundary>COALESCE(s.free_credit_reset_at,anchor) THEN UPDATE public.subscribers_public SET free_credits_remaining=5,free_credit_reset_at=boundary,monthly_ai_requests=0 WHERE user_id=p_user_id; s.free_credits_remaining:=5; s.monthly_ai_requests:=0; END IF;
 END IF;
 SELECT COALESCE(sum(remaining),0) INTO paid FROM public.credit_grants WHERE user_id=p_user_id AND environment='live' AND expires_at>now();
 SELECT COALESCE(sum(amount),0) INTO held FROM public.credit_reservations WHERE user_id=p_user_id AND status='held' AND expires_at>now();
 UPDATE public.subscribers_public SET ai_request_limit=paid+CASE WHEN s.subscribed THEN 0 ELSE s.free_credits_remaining END+COALESCE(s.monthly_ai_requests,0),extra_credits=0,rollover_credits=0 WHERE user_id=p_user_id;
 RETURN jsonb_build_object('remaining',GREATEST(0,paid+CASE WHEN s.subscribed THEN 0 ELSE s.free_credits_remaining END-held),'used',COALESCE(s.monthly_ai_requests,0),'paid_remaining',paid,'held',held,'account_status',s.account_status);
END $$;
REVOKE ALL ON FUNCTION public.refresh_credit_account(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_credit_account(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.get_my_credit_balance() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN public.refresh_credit_account(auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.get_my_credit_balance() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_my_credit_balance() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.reserve_ai_credits(p_user_id uuid,p_amount integer,p_ttl_seconds integer DEFAULT 300) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE balance jsonb; hold uuid; BEGIN
 IF p_amount IS NULL OR p_amount<=0 OR p_ttl_seconds<30 OR p_ttl_seconds>600 THEN RAISE EXCEPTION 'Invalid reservation'; END IF;
 balance:=public.refresh_credit_account(p_user_id);
 IF balance->>'account_status' IN ('suspended','missing') THEN RETURN jsonb_build_object('ok',false,'reason',CASE WHEN balance->>'account_status'='missing' THEN 'no_subscription' ELSE 'account_suspended' END); END IF;
 IF p_amount>(balance->>'remaining')::integer THEN RETURN jsonb_build_object('ok',false,'reason','limit_exceeded','remaining',balance->'remaining'); END IF;
 INSERT INTO public.credit_reservations(user_id,amount,expires_at) VALUES(p_user_id,p_amount,now()+make_interval(secs=>p_ttl_seconds)) RETURNING id INTO hold;
 RETURN jsonb_build_object('ok',true,'hold_id',hold,'remaining',(balance->>'remaining')::integer-p_amount);
END $$;
REVOKE ALL ON FUNCTION public.reserve_ai_credits(uuid,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_ai_credits(uuid,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.consume_credit_reservation(p_user_id uuid,p_hold_id uuid,p_tool_name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h record; g record; needed integer; take integer; free_available integer; BEGIN
 PERFORM public.refresh_credit_account(p_user_id);
 SELECT * INTO h FROM public.credit_reservations WHERE id=p_hold_id AND user_id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Reservation missing'; END IF;
 IF h.status='consumed' THEN RETURN jsonb_build_object('can_use',true,'duplicate',true); END IF;
 IF h.status<>'held' OR h.expires_at<=now() THEN RAISE EXCEPTION 'Reservation expired'; END IF;
 needed:=h.amount;
 SELECT CASE WHEN subscribed THEN 0 ELSE free_credits_remaining END INTO free_available FROM public.subscribers_public WHERE user_id=p_user_id;
 take:=LEAST(needed,free_available); UPDATE public.subscribers_public SET free_credits_remaining=free_credits_remaining-take WHERE user_id=p_user_id; needed:=needed-take;
 FOR g IN SELECT * FROM public.credit_grants WHERE user_id=p_user_id AND environment='live' AND expires_at>now() AND remaining>0 ORDER BY expires_at,issued_at,id FOR UPDATE LOOP
  EXIT WHEN needed=0; take:=LEAST(needed,g.remaining); UPDATE public.credit_grants SET remaining=remaining-take WHERE id=g.id; needed:=needed-take;
 END LOOP;
 IF needed>0 THEN RAISE EXCEPTION 'Reserved credits no longer available'; END IF;
 UPDATE public.credit_reservations SET status='consumed',tool_name=p_tool_name WHERE id=h.id;
 UPDATE public.subscribers_public SET monthly_ai_requests=COALESCE(monthly_ai_requests,0)+h.amount WHERE user_id=p_user_id;
 INSERT INTO public.tool_usage_analytics(user_id,tool_name,credits_used) VALUES(p_user_id,p_tool_name,h.amount);
 INSERT INTO public.credit_deduction_log(user_id,endpoint,credits_deducted,request_hash) VALUES(p_user_id,p_tool_name,h.amount,h.id::text);
 RETURN jsonb_build_object('can_use',true,'credits_charged',h.amount,'balance',public.refresh_credit_account(p_user_id));
END $$;
REVOKE ALL ON FUNCTION public.consume_credit_reservation(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_credit_reservation(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.release_credit_reservation(p_user_id uuid,p_hold_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.credit_reservations SET status='released' WHERE user_id=p_user_id AND id=p_hold_id AND status='held'; $$;
REVOKE ALL ON FUNCTION public.release_credit_reservation(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_credit_reservation(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.reset_monthly_ai_requests() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u record; BEGIN FOR u IN SELECT user_id FROM public.subscribers_public LOOP PERFORM public.refresh_credit_account(u.user_id); END LOOP; END $$;
GRANT EXECUTE ON FUNCTION public.reset_monthly_ai_requests() TO service_role;
CREATE OR REPLACE FUNCTION public.acquire_billing_lock(p_user_id uuid,p_environment text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid:=gen_random_uuid(); BEGIN IF p_environment NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'Invalid environment'; END IF; INSERT INTO public.billing_accounts(user_id,environment) VALUES(p_user_id,p_environment) ON CONFLICT DO NOTHING; UPDATE public.billing_accounts SET lock_token=token,lock_until=now()+interval '90 seconds' WHERE user_id=p_user_id AND environment=p_environment AND (lock_until IS NULL OR lock_until<now()); IF NOT FOUND THEN RETURN NULL; END IF; RETURN token; END $$;
REVOKE ALL ON FUNCTION public.acquire_billing_lock(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.acquire_billing_lock(uuid,text) TO service_role;
COMMENT ON COLUMN public.subscribers_public.ai_request_limit IS 'Compatibility projection; service-only expiring credit grants are authoritative.';